<div class="section-heading"><div><div class="eyebrow">Atendimento</div><h1>Novo agendamento</h1><p class="text-secondary mb-0">Escolha apenas horários realmente disponíveis. Folgas, férias, intervalos e conflitos já são considerados.</p></div><div class="d-flex gap-2"><a class="btn btn-light" href="/schedule/blocks">Folgas e bloqueios</a><a class="btn btn-light" href="/schedule/settings">Regras da agenda</a></div></div>
<div class="card border-0 shadow-sm"><div class="card-body"><form method="post" action="/appointments/store" data-internal-booking data-availability-url="/appointments/availability"><?= \App\Core\CSRF::field() ?><div class="row g-3">
<div class="col-md-4"><label class="form-label">Cliente</label><select name="customer_id" class="form-select" data-customer required><option value="">Selecione</option><?php foreach($customers as $c): ?><option value="<?= (int)$c['id'] ?>"><?= htmlspecialchars($c['name'],ENT_QUOTES,'UTF-8') ?></option><?php endforeach; ?></select></div>
<div class="col-md-4"><label class="form-label">Serviço</label><select name="service_id" class="form-select" data-book-service required><option value="">Selecione</option><?php foreach($services as $s): ?><option value="<?= (int)$s['id'] ?>"><?= htmlspecialchars($s['name'],ENT_QUOTES,'UTF-8') ?> — R$ <?= number_format((float)$s['price'],2,',','.') ?></option><?php endforeach; ?></select></div>
<div class="col-md-4"><label class="form-label">Profissional</label><select name="professional_id" class="form-select" data-book-professional required><option value="">Selecione</option><?php foreach($professionals as $p): ?><option value="<?= (int)$p['id'] ?>"><?= htmlspecialchars($p['name'],ENT_QUOTES,'UTF-8') ?></option><?php endforeach; ?></select></div>
<?php if($vehicles):?><div class="col-md-4"><label class="form-label">Veículo</label><select name="vehicle_id" class="form-select"><option value="">Sem veículo</option><?php foreach($vehicles as $v):?><option value="<?=(int)$v['id']?>" data-customer="<?=(int)$v['customer_id']?>"><?=htmlspecialchars($v['label'])?></option><?php endforeach;?></select></div><?php endif;?>
<div class="col-md-4"><label class="form-label">Data</label><input name="booking_date" type="date" class="form-control" data-book-date min="<?=date('Y-m-d')?>" required></div><div class="col-12"><label class="form-label">Horários livres</label><div class="d-flex flex-wrap gap-2" data-book-slots><span class="text-secondary">Escolha serviço, profissional e data.</span></div><input type="hidden" name="starts_at" data-book-start required></div><div class="col-12"><label class="form-label">Observação</label><textarea class="form-control" name="notes" rows="2"></textarea></div></div><div class="mt-3"><button class="btn btn-primary" data-book-submit disabled>Agendar</button> <a href="/appointments" class="btn btn-light">Cancelar</a></div></form></div></div>
